using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Typed metadata for Person: {personInfo.Type.Name}");

// Round-trip using the typed info
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
var person = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Deserialized: {person}");

// 2) Probe without throwing: TryGetTypeInfo returns false if metadata isn't available.
//    Use a resolver that only knows about int, so string will miss.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
        .WithAddedModifier(ti =>
        {
            // Allow everything normally — we'll demo with an empty resolver below.
        })
};

// Build a truly limited resolver via JsonTypeInfoResolver.Combine with nothing:
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // resolves nothing
};

if (empty.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? result))
{
    Console.WriteLine($"Found metadata: {result!.Type.Name}");
}
else
{
    Console.WriteLine("No metadata for Person — and no exception was thrown.");
}

record Person(string Name, int Age);

